cd app && cat > /tmp/quick-debug.mjs << 'EOF'
import { createShard, spawnShip, addConnection, pushPlayerInput } from "./src/server/shard/index.js";
import { TICK_S } from "./src/server/shard/sim.js";

let now = 0;
const broadcasts = [];
const shard = createShard({
  systemId: "test-system",
  context: { system: { systemId: "test", star: { id: "s1", name: "S", position: {x:0,y:0,z:0}, spectralClass: "G", temperatureK: 5000, radiusKm: 1, massSolar: 1, habitableZoneAU: 1, hasAtmosphere: false }, planets: [], aiRoster: [], tradeCommodities: [], version: 1, seed: "x" }, planetById: () => undefined, heightAtFor: () => undefined, tileSizeM: 64 },
  send: () => {},
  broadcast: (tick, entities, lastAppliedSeq) => {
    broadcasts.push({ tick, entities, lastAppliedSeq: {...lastAppliedSeq} });
  },
  onTickObserver: null,
  autoStart: false,
});

addConnection(shard, { connId: "c1", callsign: "A", playerId: "p1", entityId: null, lastSeq: 0, pendingInput: null, staleDrops: 0 });
spawnShip(shard, { shipId: "s1", playerId: "p1", callsign: "A", classId: "scout", hull: 100, shields: 50, pos: {x:0,y:0,z:0}, regime: "space", bindConnId: "c1" });
pushPlayerInput(shard, "c1", { seq: 1, thrust: 0.5, turn: 0, pitch: 0, yaw: 0, fire: false, lock: false, action: null });
pushPlayerInput(shard, "c1", { seq: 2, thrust: 0.5, turn: 0, pitch: 0, yaw: 0, fire: false, lock: false, action: null });
pushPlayerInput(shard, "c1", { seq: 3, thrust: 0.5, turn: 0, pitch: 0, yaw: 0, fire: false, lock: false, action: null });

const fakeNow = () => now;
shard.sim.hooks.clock = fakeNow;

// Prime
now += TICK_S * 1000;
shard.sim.tick();
for (let i = 0; i < 4; i++) {
  now += TICK_S * 1000;
  shard.sim.tick();
}
console.log("broadcasts", JSON.stringify(broadcasts, null, 2));
shard.shutdown();
EOF
npx tsx /tmp/quick-debug.mjs 2>&1 | tail -50
